<?php
declare(strict_types=1);namespace Pam\Native\Intents;use InvalidArgumentException;use JsonSerializable;final readonly class IntentAction implements JsonSerializable{public function __construct(public string$identifier,public string$title,public string$deepLink,public string$subtitle=''){if(preg_match('/^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/D',$identifier)!==1||$title===''||strlen($title)>80||strlen($subtitle)>120)throw new InvalidArgumentException('Invalid intent action metadata.');if(!preg_match('/^[a-z][a-z0-9+.-]*:\/\//iD',$deepLink)||strlen($deepLink)>2048)throw new InvalidArgumentException('Invalid intent deep link.');}public function jsonSerialize():array{return['id'=>$this->identifier,'title'=>$this->title,'subtitle'=>$this->subtitle,'deepLink'=>$this->deepLink];}}
